function getIcon(name) {
  return ICON_MAP[norm(name)] || null;
}

/* ── Reveal-on-scroll wrapper ── */
function Reveal({ children, delay = 0, className = "" }) {
  const [shown, setShown] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setShown(true); obs.disconnect(); } },
      { threshold: 0.12 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <div ref={ref} className={`reveal${shown ? " reveal-in" : ""} ${className}`} style={{ transitionDelay: `${delay}s` }}>
      {children}
    </div>
  );
}

/* ── Skill Bar ── */
function SkillRow({ name, pct, delay }) {
  const [w, setW] = useState(0);
  const ref = useRef(null);
  const match = getIcon(name);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) setW(pct); }, { threshold: 0.1 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [pct]);
  return (
    <div ref={ref} style={{ marginBottom: 20 }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 8, color: "#bbb", fontFamily: "var(--mono)", letterSpacing: 1 }}>
          {match && <match.Icon size={15} color={match.color} style={{ flexShrink: 0, filter: "drop-shadow(0 0 4px rgba(0,0,0,.4))" }} />}
          {name}
        </span>
        <span style={{ fontSize: 14, color: "#fffefe", fontFamily: "var(--mono)" }}>{pct}%</span>
      </div>
      <div style={{ height: 2, background: "#181818" }}>
        <div style={{ height: "100%", background: "linear-gradient(90deg,#39ff14,#00e5cc)", width: `${w}%`, transition: `width 1.1s cubic-bezier(.4,0,.2,1) ${delay}s` }} />
      </div>
    </div>
  );
}

