/* ── Animated Counter ── */
function Counter({ target, suffix = "" }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) {
        const t = parseFloat(String(target).replace(/[^0-9.]/g,""));
        const isFloat = String(target).includes(".");
        let s = 0; const step = t / 40;
        const timer = setInterval(() => {
          s += step;
          if (s >= t) { setVal(t); clearInterval(timer); }
          else setVal(isFloat ? parseFloat(s.toFixed(1)) : Math.floor(s));
        }, 30);
      }
    }, { threshold: 0.3 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [target]);
  return <span ref={ref}>{val}{suffix}</span>;
}

/* ── Fluid Canvas ── */
function FluidCanvas() {
  const ref = useRef(null);
  useEffect(() => {
    const canvas = ref.current; if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let w = canvas.width = window.innerWidth;
    let h = canvas.height = window.innerHeight;
    let t = 0;
    const blobs = Array.from({ length: 6 }, (_, i) => ({
      x: Math.random()*w, y: Math.random()*h,
      vx: (Math.random()-.5)*.35, vy: (Math.random()-.5)*.25,
      r: 160+Math.random()*140, hue: 140+i*25,
    }));
    let raf;
    const draw = () => {
      ctx.clearRect(0,0,w,h); t += .003;
      blobs.forEach(b => {
        b.x += b.vx + Math.sin(t+b.r)*.28;
        b.y += b.vy + Math.cos(t+b.r)*.18;
        if (b.x < -b.r) b.x=w+b.r; if (b.x > w+b.r) b.x=-b.r;
        if (b.y < -b.r) b.y=h+b.r; if (b.y > h+b.r) b.y=-b.r;
        const g = ctx.createRadialGradient(b.x,b.y,0,b.x,b.y,b.r);
        g.addColorStop(0,`hsla(${b.hue},85%,38%,0.16)`);
        g.addColorStop(.55,`hsla(${b.hue+25},70%,28%,0.07)`);
        g.addColorStop(1,"transparent");
        ctx.beginPath(); ctx.fillStyle=g; ctx.arc(b.x,b.y,b.r,0,Math.PI*2); ctx.fill();
      });
      raf = requestAnimationFrame(draw);
    };
    draw();
    const resize = () => { w=canvas.width=window.innerWidth; h=canvas.height=window.innerHeight; };
    window.addEventListener("resize",resize);
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize",resize); };
  }, []);
  return <canvas ref={ref} style={{ position:"absolute", inset:0, width:"100%", height:"100%" }} />;
}

/* ── Boot-sequence preloader ── */
const BOOT_LINES = ["INITIALISING PORTFOLIO...", "LOADING ASSETS...", "COMPILING EXPERIENCE...", "READY."];
function Preloader({ done }) {
  const [line, setLine] = useState(0);
  useEffect(() => {
    const iv = setInterval(() => setLine(l => Math.min(l + 1, BOOT_LINES.length - 1)), 260);
    return () => clearInterval(iv);
  }, []);
  return (
    <div className={`preloader${done ? " out" : ""}`}>
      <div className="preloader-inner">
        <div className="preloader-logo">TW<span className="green">.</span>DEV</div>
        {BOOT_LINES.slice(0, line + 1).map((l, i) => (
          <div key={i} className="preloader-line">
            <span className="green">→</span> {l}
          </div>
        ))}
        <div className="preloader-bar"><div className="preloader-bar-fill" /></div>
      </div>
    </div>
  );
}

/* ── Scroll progress bar ── */
function ScrollProgress() {
  const [p, setP] = useState(0);
  useEffect(() => {
    const onScroll = () => {
      const h = document.documentElement;
      const max = h.scrollHeight - h.clientHeight;
      setP(max > 0 ? (h.scrollTop / max) * 100 : 0);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return <div className="scroll-progress" style={{ width: `${p}%` }} />;
}

/* ── Back to top ── */
function BackToTop() {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const onScroll = () => setShow(window.scrollY > 700);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <button
      className={`back-to-top${show ? " show" : ""}`}
      onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      aria-label="Back to top"
    >
      <FiArrowUp size={16} />
    </button>
  );
}

